package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.sharedKernel.businesslogic.media.PrivateImageStore;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.DateTimeProvider;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.gateways.AvatarMediaRepository;import java.time.Duration;
public final class CleanAvatarMediaObjects{private final AvatarMediaRepository media;private final PrivateImageStore store;private final CompleteAvatarMediaDeletion completion;private final DateTimeProvider clock;private final Duration pendingTtl;public CleanAvatarMediaObjects(AvatarMediaRepository media,PrivateImageStore store,CompleteAvatarMediaDeletion completion,DateTimeProvider clock,Duration pendingTtl){this.media=media;this.store=store;this.completion=completion;this.clock=clock;this.pendingTtl=pendingTtl;}public void run(int limit){for(var item:media.cleanupCandidates(clock.now().minus(pendingTtl),limit)){var s=item.snapshot();store.delete(s.pendingObjectKey());store.delete(s.objectKey());completion.complete(s.mediaId());}}}
